sys_script.script:
(function executeRule(current, previous) {

    var startDT = current.getValue('start_date_time') || '';
    var endDT = current.getValue('end_date_time') || '';

    if (startDT && startDT.length >= 15) {
        current.setValue('start', convertScheduleDateTime(startDT));
    }

    if (endDT && endDT.length >= 15) {
        current.setValue('end', convertScheduleDateTime(endDT));
    }

    function convertScheduleDateTime(sdt) {
        // Input: "20260827T054920" (yyyyMMddTHHmmss)
        // Output: "2026-08-27 05:49:20" (yyyy-MM-dd HH:mm:ss)
        var year = sdt.substring(0, 4);
        var month = sdt.substring(4, 6);
        var day = sdt.substring(6, 8);
        var hour = sdt.substring(9, 11);
        var min = sdt.substring(11, 13);
        var sec = sdt.substring(13, 15);
        return year + '-' + month + '-' + day + ' ' + hour + ':' + min + ':' + sec;
    }

})(current, previous);
